import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Model Studio cheatsheet","description":"Regions, keys, base URLs, plan comparison. Full model tables and unit prices stay on official pages.","frontmatter":{"title":"Model Studio cheatsheet","description":"Regions, keys, base URLs, plan comparison. Full model tables and unit prices stay on official pages.","domain":"product","tags":["model-platform"],"role":"cheatsheet"},"headers":[],"relativePath":"products/bailian/bailian-cheatsheet.md","filePath":"products/bailian/bailian-cheatsheet.md","lastUpdated":1787107158000}'),d={name:"products/bailian/bailian-cheatsheet.md"};function l(n,t,i,s,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="model-studio-cheatsheet" tabindex="-1">Model Studio cheatsheet <a class="header-anchor" href="#model-studio-cheatsheet" aria-label="Permalink to &quot;Model Studio cheatsheet&quot;">​</a></h1><blockquote><p>Lookup only. Learn on the <a href="./index.html">map</a> and <a href="./bailian.html">tutorial</a>. Concepts in the <a href="./bailian-glossary.html">glossary</a>.</p></blockquote><p><strong>Last verified: 2026-08-19.</strong> Trust the official page you have open for IDs, prices, and hosts.</p><h2 id="which-path" tabindex="-1">Which path <a class="header-anchor" href="#which-path" aria-label="Permalink to &quot;Which path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Job</th><th>Use</th><th>Official page</th></tr></thead><tbody><tr><td>Call models from your service</td><td>PAYG API, OpenAI-compatible</td><td><a href="https://help.aliyun.com/zh/model-studio/first-api-call-to-qwen" target="_blank" rel="noreferrer">First API call</a></td></tr><tr><td>Monthly quota inside coding tools</td><td>Token Plan (recommended for new buys) or Coding Plan</td><td><a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan</a>, <a href="https://help.aliyun.com/zh/model-studio/coding-plan" target="_blank" rel="noreferrer">Coding Plan</a></td></tr><tr><td>No-code Q&amp;A / agent</td><td>Console app, prefer Agent 2.0</td><td><a href="https://help.aliyun.com/zh/model-studio/new-single-agent-application" target="_blank" rel="noreferrer">Agent 2.0</a></td></tr><tr><td>Local agent, multimodal tools</td><td>CLI <code>bl</code></td><td><a href="https://bailian.aliyun.com/cli/install.md" target="_blank" rel="noreferrer">Install</a></td></tr><tr><td>Chat only</td><td>Qwen (#83)</td><td>Not Model Studio</td></tr><tr><td>Alibaba coding IDE</td><td>Qoder CN / Lingma (#84)</td><td><a href="https://help.aliyun.com/zh/model-studio/lingma-agent" target="_blank" rel="noreferrer">Attach page</a></td></tr></tbody></table><h2 id="regions" tabindex="-1">Regions <a class="header-anchor" href="#regions" aria-label="Permalink to &quot;Regions&quot;">​</a></h2><p>China-site intro (2026-08-19): China (Beijing), US (Virginia), Singapore, Germany (Frankfurt), Japan (Tokyo).</p><table tabindex="0"><thead><tr><th>Fact</th><th>Source</th></tr></thead><tbody><tr><td>Keys, endpoints, models, features, prices are per region</td><td><a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">Intro</a></td></tr><tr><td>China-site new-user quota is Beijing only</td><td><a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">Free quota</a></td></tr><tr><td>International intro puts free quota in Singapore</td><td><a href="https://www.alibabacloud.com/help/en/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">What is Model Studio</a></td></tr><tr><td>Token Plan is Beijing only</td><td><a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan</a></td></tr><tr><td>International sidebar also lists China (Hong Kong)</td><td>International intro; absent from the China-site intro. Use the site you are on</td></tr></tbody></table><p>You cannot turn the service off after activation. Stop calls by deleting keys. <a href="https://help.aliyun.com/zh/model-studio/faq-about-alibaba-cloud-model-studio" target="_blank" rel="noreferrer">FAQ</a></p><h2 id="api-keys" tabindex="-1">API keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Official value</th></tr></thead><tbody><tr><td>Env var</td><td><code>DASHSCOPE_API_KEY</code></td></tr><tr><td>PAYG after the security upgrade</td><td><code>sk-ws…</code>, shown once</td></tr><tr><td>PAYG from before the upgrade</td><td><code>sk-…</code>, still valid</td></tr><tr><td>Coding Plan / Token Plan dedicated</td><td><code>sk-sp-</code></td></tr><tr><td>Beijing / Singapore / Tokyo / Frankfurt</td><td>50 keys per primary account per region</td></tr><tr><td>US (Virginia)</td><td>20 per owning account; no disable/reset</td></tr><tr><td>Expiry</td><td>None; delete to revoke</td></tr><tr><td>RAM user deleted</td><td>That user&#39;s keys die</td></tr></tbody></table><p>Source: <a href="https://help.aliyun.com/zh/model-studio/get-api-key" target="_blank" rel="noreferrer">Get an API key</a>.</p><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><p>Replace <code>{WorkspaceId}</code> with the workspace ID from the console.</p><table tabindex="0"><thead><tr><th>Region</th><th>OpenAI-compatible (model list / first call)</th><th>Anthropic-compatible (model list)</th></tr></thead><tbody><tr><td>China (Beijing)</td><td><code>https://{WorkspaceId}.cn-beijing.maas.aliyuncs.com/compatible-mode/v1</code></td><td><code>https://{WorkspaceId}.cn-beijing.maas.aliyuncs.com/apps/anthropic</code></td></tr><tr><td>Singapore</td><td><code>https://{WorkspaceId}.ap-southeast-1.maas.aliyuncs.com/compatible-mode/v1</code></td><td><code>https://{WorkspaceId}.ap-southeast-1.maas.aliyuncs.com/apps/anthropic</code></td></tr><tr><td>Japan (Tokyo)</td><td><code>https://{WorkspaceId}.ap-northeast-1.maas.aliyuncs.com/compatible-mode/v1</code></td><td><code>https://{WorkspaceId}.ap-northeast-1.maas.aliyuncs.com/apps/anthropic</code></td></tr><tr><td>Germany (Frankfurt)</td><td><code>https://{WorkspaceId}.eu-central-1.maas.aliyuncs.com/compatible-mode/v1</code></td><td><code>https://{WorkspaceId}.eu-central-1.maas.aliyuncs.com/apps/anthropic</code></td></tr><tr><td>US (Virginia)</td><td><code>https://dashscope-us.aliyuncs.com/compatible-mode/v1</code> (<a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">model list</a>)</td><td><code>https://dashscope-us.aliyuncs.com/apps/anthropic</code></td></tr></tbody></table><p>DashScope native hosts use <code>/api/v1</code> on the same model-list page.</p><p><strong>Official pages disagree — this table picks a winner:</strong></p><ul><li>The intro sample still shows <code>{WorkspaceId}.us-east-1.maas.aliyuncs.com</code> for Virginia. The US row follows the <strong>model list</strong>.</li><li>Coding Plan still lists PAYG OpenAI as <code>https://dashscope.aliyuncs.com/compatible-mode/v1</code>. New code follows <strong>first call / model list</strong>.</li></ul><p>Coding Plan dedicated:</p><ul><li>OpenAI: <code>https://coding.dashscope.aliyuncs.com/v1</code></li><li>Anthropic: <code>https://coding.dashscope.aliyuncs.com/apps/anthropic</code></li></ul><p>Token Plan dedicated hosts come from the Token Plan console. Do not reuse the Coding Plan row.</p><h2 id="how-to-look-up-models" tabindex="-1">How to look up models <a class="header-anchor" href="#how-to-look-up-models" aria-label="Permalink to &quot;How to look up models&quot;">​</a></h2><p>Do not maintain a full catalog here.</p><ul><li><a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">Models (ZH)</a> / <a href="https://www.alibabacloud.com/help/en/model-studio/models" target="_blank" rel="noreferrer">Models (EN)</a></li><li><a href="https://help.aliyun.com/zh/model-studio/model-pricing" target="_blank" rel="noreferrer">Pricing</a></li></ul><p>Intro tiers: Max = strongest; Plus = default recommendation; Flash = low latency. The 2026-08 intro names <code>qwen3.8-max</code>. The first-call sample uses <code>qwen-plus</code>.</p><p>FAQ: <code>qwen-plus-latest</code> is Qwen3, <strong>not</strong> an alias of Qwen3.5 / Qwen3.7. Those are sibling series.</p><h2 id="plan-comparison-numbers-move-checkout-wins" tabindex="-1">Plan comparison (numbers move; checkout wins) <a class="header-anchor" href="#plan-comparison-numbers-move-checkout-wins" aria-label="Permalink to &quot;Plan comparison (numbers move; checkout wins)&quot;">​</a></h2><p>From <a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan</a> and <a href="https://help.aliyun.com/zh/model-studio/coding-plan" target="_blank" rel="noreferrer">Coding Plan</a> as opened 2026-08-19:</p><table tabindex="0"><thead><tr><th></th><th>Token Plan Personal</th><th>Token Plan Team</th><th>Coding Plan Pro</th></tr></thead><tbody><tr><td>Meter</td><td>Credits, 7-day window</td><td>Credits / seat / month</td><td>Request counts (5-hour / week / month caps; first hit wins)</td></tr><tr><td>List price on that day</td><td>Lite CNY 39/mo promo (60); Standard 139 (180); Pro 499 (600)</td><td>Standard seat 150 promo (198); Pro 550 (698); Max 1,398</td><td>CNY 200/mo; the page has mentioned a 39.90 first month — checkout wins</td></tr><tr><td>Region</td><td>Beijing only</td><td>Beijing only</td><td>See that page</td></tr><tr><td>Training data</td><td>Personal <strong>is</strong> used to improve the service (intro &quot;Important&quot;)</td><td>Team: no training-use commitment</td><td>Inputs and outputs <strong>are</strong> used to improve the service</td></tr><tr><td>Refunds</td><td>That page / the agreement</td><td>That page / the agreement</td><td>Official: <strong>no refunds</strong></td></tr><tr><td>Status</td><td>Official recommendation for new buys</td><td>Multi-seat</td><td>Lite: no new buys after 2026-03-20, no renewals after 2026-04-13; Pro is limited stock</td></tr></tbody></table><p>Coding Plan Pro caps on that page: 6,000 / 5 hours, 45,000 / week, 90,000 / month. Simple tasks ~5–10 requests; hard ones ~10–30+.</p><p>PAYG realtime offset order: new-user quota &gt; resource pack &gt; savings plan &gt; account balance. <a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">Free quota</a>, <a href="https://help.aliyun.com/zh/model-studio/billing-for-model-studio" target="_blank" rel="noreferrer">Billing</a></p><p>Batch is 50% of realtime and <strong>cannot</strong> use free quota / savings / packs.</p><p>Wanxiang membership does not offset Model Studio API. <a href="https://help.aliyun.com/zh/model-studio/faq-about-alibaba-cloud-model-studio" target="_blank" rel="noreferrer">FAQ</a></p><h2 id="model-studio-cli" tabindex="-1">Model Studio CLI <a class="header-anchor" href="#model-studio-cli" aria-label="Permalink to &quot;Model Studio CLI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Official value</th></tr></thead><tbody><tr><td>npm package</td><td><code>bailian-cli</code></td></tr><tr><td>Commands</td><td><code>bl</code>, <code>bailian</code></td></tr><tr><td>Node</td><td>≥ 22.12.0</td></tr><tr><td>Install</td><td><code>npm install -g bailian-cli</code> (not pnpm / yarn for this package)</td></tr><tr><td>Login</td><td><code>bl auth login --console</code></td></tr><tr><td>Smoke test</td><td><code>bl text chat --message &quot;ping&quot; --non-interactive --output json</code></td></tr><tr><td>Region flag</td><td><code>--region cn|us|intl</code>, default <code>cn</code></td></tr></tbody></table><p>Not <code>aliyun bailian</code>.</p><h2 id="glossary-index" tabindex="-1">Glossary index <a class="header-anchor" href="#glossary-index" aria-label="Permalink to &quot;Glossary index&quot;">​</a></h2><p>One line each; definitions on the glossary page.</p><table tabindex="0"><thead><tr><th>Term</th><th>Hook</th></tr></thead><tbody><tr><td><a href="./bailian-glossary.html#model-studio">Model Studio</a></td><td>Platform, not a chat window</td></tr><tr><td><a href="./bailian-glossary.html#qwen">Qwen</a></td><td>Model family and another product</td></tr><tr><td><a href="./bailian-glossary.html#lingma--qoder-cn">Lingma / Qoder CN</a></td><td>IDE</td></tr><tr><td><a href="./bailian-glossary.html#dashscope">DashScope</a></td><td>Legacy API brand; the env var remains</td></tr><tr><td><a href="./bailian-glossary.html#workspace">Workspace</a></td><td>Isolation for ACL and bills</td></tr><tr><td><a href="./bailian-glossary.html#three-call-protocols">Three protocols</a></td><td>OpenAI / Anthropic / DashScope</td></tr><tr><td><a href="./bailian-glossary.html#token-plan-vs-coding-plan">Token Plan vs Coding Plan</a></td><td>Two subscriptions that cannot migrate</td></tr><tr><td><a href="./bailian-glossary.html#agent-10-vs-20">Agent 1.0 vs 2.0</a></td><td>No upgrade path</td></tr><tr><td><a href="./bailian-glossary.html#model-studio-cli-vs-alibaba-cloud-cli">Two CLIs</a></td><td><code>bl</code> ≠ <code>aliyun bailian</code></td></tr></tbody></table><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p><strong>Last systematic pass: 2026-08-19.</strong></p><h3 id="s-official-source-of-truth" tabindex="-1">S: official source of truth <a class="header-anchor" href="#s-official-source-of-truth" aria-label="Permalink to &quot;S: official source of truth&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">What is Model Studio (ZH)</a></td><td>Definition, regions, billing boundary</td></tr><tr><td><a href="https://www.alibabacloud.com/help/en/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">What is Model Studio (EN)</a></td><td>International nav and regions</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">Models</a></td><td>IDs, regions, three base URLs</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/first-api-call-to-qwen" target="_blank" rel="noreferrer">First API call</a></td><td>Activation, samples</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/get-api-key" target="_blank" rel="noreferrer">Get an API key</a></td><td>Key format, caps, env var</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/billing-for-model-studio" target="_blank" rel="noreferrer">Billing items</a></td><td>Inference / train / deploy</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/model-pricing" target="_blank" rel="noreferrer">Pricing</a></td><td>Unit prices</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">Free quota</a></td><td>90 days, stop switch</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan</a></td><td>Credits plans</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/coding-plan" target="_blank" rel="noreferrer">Coding Plan</a></td><td>Request plans, dedicated URL</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/use-chat-client-or-development-tool/" target="_blank" rel="noreferrer">Clients</a></td><td>Third-party tools</td></tr><tr><td><a href="https://bailian.aliyun.com/cli/install.md" target="_blank" rel="noreferrer">CLI install</a></td><td><code>bailian-cli</code></td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/faq-about-alibaba-cloud-model-studio" target="_blank" rel="noreferrer">FAQ</a></td><td>Activate / cannot disable / vs Qwen</td></tr></tbody></table><h3 id="a-official-but-marketing-or-slow" tabindex="-1">A: official but marketing or slow <a class="header-anchor" href="#a-official-but-marketing-or-slow" aria-label="Permalink to &quot;A: official but marketing or slow&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://www.aliyun.com/product/bailian" target="_blank" rel="noreferrer">China product page</a></td><td>Positioning; numbers lose to the help center</td></tr><tr><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">Console</a></td><td>Real activation and quota</td></tr><tr><td><a href="https://bailian.console.aliyun.com/cli" target="_blank" rel="noreferrer">CLI landing</a></td><td>CLI capabilities</td></tr><tr><td><a href="https://help.aliyun.com/zh/model-studio/privacy-notice" target="_blank" rel="noreferrer">Privacy</a></td><td>Cross-check plan data-use text</td></tr><tr><td><a href="https://terms.alicdn.com/legal-agreement/terms/common_platform_service/20230728213935489/20230728213935489.html" target="_blank" rel="noreferrer">Service agreement</a></td><td>§5.2 (named by Coding Plan)</td></tr></tbody></table><h3 id="b-verify" tabindex="-1">B: verify <a class="header-anchor" href="#b-verify" aria-label="Permalink to &quot;B: verify&quot;">​</a></h3><p>Community posts. IDs and hosts rot fast. Commands come from S only.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./index.html">Map</a></li><li><a href="./bailian.html">Tutorial</a></li><li><a href="./bailian-cookbook.html">Cookbook</a></li><li><a href="./bailian-glossary.html">Glossary</a></li></ul>',49)])])}const g=e(d,[["render",l]]);export{b as __pageData,g as default};
